-- Replacement backend only. Does not import, claim, or modify legacy game rows.
-- Generated by Supabase CLI; local review only, not a remote cutover.
begin;
create schema beauty_game;
revoke all on schema beauty_game from public, anon, authenticated;
grant usage on schema beauty_game to service_role;

create table beauty_game.session_creation_budget (
  singleton boolean primary key default true check (singleton),
  window_started_at timestamptz not null default clock_timestamp(),
  creations integer not null default 0 check (creations >= 0)
);
insert into beauty_game.session_creation_budget(singleton) values(true);
create table beauty_game.sessions (
  session_hash text primary key check (session_hash ~ '^[0-9a-f]{64}$'),
  device_id uuid not null unique default gen_random_uuid(),
  user_id uuid references auth.users(id),
  linked_at timestamptz,
  created_at timestamptz not null default now(),
  rate_started_at timestamptz not null default clock_timestamp(),
  rate_count integer not null default 0 check (rate_count >= 0)
);
create table beauty_game.answers (
  session_hash text not null references beauty_game.sessions(session_hash),
  play uuid not null, character text not null check (length(character) between 1 and 120),
  test boolean not null, version text not null check (length(version) <= 80),
  product text not null check (length(product) between 1 and 240),
  reason jsonb not null check (jsonb_typeof(reason) = 'object'),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  primary key (session_hash, play, character, test)
);
create index answers_stats on beauty_game.answers(test, character);
create table beauty_game.events (
  id uuid primary key, session_hash text not null references beauty_game.sessions(session_hash),
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  created_at timestamptz not null default now()
);
create index events_session on beauty_game.events(session_hash);
create table beauty_game.experiences (
  session_hash text not null references beauty_game.sessions(session_hash),
  play uuid not null, character text not null check (length(character) between 1 and 120),
  test boolean not null, experience text not null check (length(experience) <= 2000),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  primary key (session_hash, play, character, test)
);
alter table beauty_game.experiences add constraint experiences_owned_answer_fk
  foreign key (session_hash,play,character,test) references beauty_game.answers(session_hash,play,character,test);
create table beauty_game.reflections (
  session_hash text not null references beauty_game.sessions(session_hash),
  play uuid not null, character text not null check (length(character) between 1 and 120),
  test boolean not null, mode text not null check (length(mode) between 1 and 80),
  body text not null check (length(body) <= 6000), criteria jsonb not null check (jsonb_typeof(criteria) = 'array'),
  language text not null check (length(language) between 1 and 20),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  primary key (session_hash, play, character, test)
);
create table beauty_game.shares (
  id uuid primary key default gen_random_uuid(),
  session_hash text not null references beauty_game.sessions(session_hash),
  play uuid not null, character text not null, test boolean not null,
  content_hash text not null, product text not null, reason jsonb not null,
  snapshot jsonb not null check (jsonb_typeof(snapshot) = 'object'),
  channel text not null check (length(channel) <= 80), created_at timestamptz not null default now(),
  unique (session_hash, play, character, test, content_hash)
);
-- RLS is defense in depth. Only the existing trusted service role receives access.
alter table beauty_game.session_creation_budget enable row level security;
alter table beauty_game.sessions enable row level security;
alter table beauty_game.answers enable row level security;
alter table beauty_game.events enable row level security;
alter table beauty_game.experiences enable row level security;
alter table beauty_game.reflections enable row level security;
alter table beauty_game.shares enable row level security;
revoke all on all tables in schema beauty_game from public, anon, authenticated;
grant select, update on beauty_game.session_creation_budget to service_role;
grant select, insert, update on beauty_game.sessions, beauty_game.answers, beauty_game.experiences, beauty_game.reflections to service_role;
grant select, insert on beauty_game.events, beauty_game.shares to service_role;
grant delete on beauty_game.experiences to service_role;

create function public.beauty_game_command(p_action text, p_session_hash text, p_payload jsonb)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  v_session beauty_game.sessions%rowtype;
  v_budget beauty_game.session_creation_budget%rowtype;
  v_answer beauty_game.answers%rowtype;
  v_share beauty_game.shares%rowtype;
  v_existing beauty_game.events%rowtype;
  v_play uuid; v_id uuid; v_user uuid; v_character text; v_test boolean;
  v_reason jsonb; v_public_reason jsonb; v_hash text; v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_action is null or p_action not in ('session','event','answer','experience','share','reflection','invite','stats','link')
     or p_session_hash is null or p_session_hash !~ '^[0-9a-f]{64}$'
     or p_payload is null or jsonb_typeof(p_payload) <> 'object' or octet_length(p_payload::text) > 32768 then
    return '{"error":"invalid_request","status":400}'::jsonb;
  end if;
  if p_action = 'session' and not exists (select 1 from beauty_game.sessions where session_hash = p_session_hash) then
    -- Global creation cap limits cookie rotation abuse without storing IP addresses.
    select * into v_budget from beauty_game.session_creation_budget where singleton for update;
    -- Another request may have registered this exact hash while we waited.
    if not exists (select 1 from beauty_game.sessions where session_hash = p_session_hash) then
      if v_now >= v_budget.window_started_at + interval '1 minute' then
        update beauty_game.session_creation_budget set window_started_at = v_now, creations = 1 where singleton;
      elsif v_budget.creations >= 300 then
        return '{"error":"rate_limited","status":429}'::jsonb;
      else
        update beauty_game.session_creation_budget set creations = creations + 1 where singleton;
      end if;
      insert into beauty_game.sessions(session_hash) values(p_session_hash);
    end if;
  end if;
  select * into v_session from beauty_game.sessions where session_hash = p_session_hash for update;
  if not found then return '{"error":"session_required","status":401}'::jsonb; end if;
  -- Serialize every command on this session, including retries and failed validations.
  if v_now >= v_session.rate_started_at + interval '1 minute' then
    update beauty_game.sessions set rate_started_at = v_now, rate_count = 1 where session_hash = p_session_hash;
  elsif v_session.rate_count >= 240 then
    return '{"error":"rate_limited","status":429}'::jsonb;
  else
    update beauty_game.sessions set rate_count = rate_count + 1 where session_hash = p_session_hash;
  end if;
  if p_action = 'session' then return jsonb_build_object('ok',true,'device_id',v_session.device_id); end if;
  -- Validation exceptions are caught inside this subtransaction so rate consumption survives.
  begin
    if p_action = 'link' then
      if p_payload->'consent' is distinct from 'true'::jsonb then return '{"error":"consent_required","status":400}'::jsonb; end if;
      v_user := (p_payload->>'user_id')::uuid;
      if v_user is null then
        return '{"error":"invalid_user","status":400}'::jsonb;
      end if;
      if v_session.user_id is not null and v_session.user_id <> v_user then
        return '{"error":"already_linked","status":409}'::jsonb;
      end if;
      update beauty_game.sessions set user_id = v_user, linked_at = coalesce(linked_at,v_now) where session_hash = p_session_hash;
      return '{"ok":true}'::jsonb;
    end if;
    if p_action = 'stats' then
      if jsonb_typeof(p_payload->'characters') is distinct from 'array' or jsonb_array_length(p_payload->'characters') not between 1 and 100
         or jsonb_typeof(p_payload->'test') is distinct from 'boolean' then return '{"error":"invalid_request","status":400}'::jsonb; end if;
      -- Full cohort, not PostgREST's 1000-row default. Server MUST aggregate before HTTP response.
      select coalesce(jsonb_agg(jsonb_build_object('character',a.character,'product',a.product,'reason',a.reason::text,'test',a.test,'experience',e.experience)), '[]'::jsonb)
        into v_result from beauty_game.answers a
        left join beauty_game.experiences e on e.session_hash = a.session_hash and e.play = a.play and e.character = a.character and e.test = a.test
        where a.test = (p_payload->>'test')::boolean and a.character in (select jsonb_array_elements_text(p_payload->'characters'));
      return jsonb_build_object('answers',v_result);
    end if;
    if p_action = 'invite' then
      v_id := (p_payload->>'id')::uuid;
      select * into v_share from beauty_game.shares where id = v_id;
      if not found then return '{"error":"not_found","status":404}'::jsonb; end if;
      v_result := jsonb_build_object('id',v_share.id,'character',v_share.character,'test',v_share.test,'snapshot',v_share.snapshot);
      if p_payload->'reveal' = 'true'::jsonb then
        v_play := (p_payload->>'play')::uuid;
        if not exists (select 1 from beauty_game.answers where session_hash = p_session_hash and play = v_play
           and character = v_share.character and test = v_share.test) then
          return '{"error":"answer_required","status":403}'::jsonb;
        end if;
        v_result := v_result || jsonb_build_object('product',v_share.product,'reason',case when jsonb_typeof(v_share.reason->'reasons') = 'array' then (select coalesce(string_agg(value, ', '), '') from jsonb_array_elements_text(v_share.reason->'reasons')) else coalesce(v_share.reason->>'reasons','') end,
          'shade',v_share.reason->'shade','advice',v_share.reason->'advice');
      end if;
      return v_result;
    end if;
    v_play := (p_payload->>'play')::uuid;
    v_character := p_payload->>'character';
    if v_play is null or v_character is null or length(v_character) not between 1 and 120
       or jsonb_typeof(p_payload->'test') is distinct from 'boolean' then
      return '{"error":"invalid_request","status":400}'::jsonb;
    end if;
    v_test := (p_payload->>'test')::boolean;
    if p_action = 'event' then
      v_id := (p_payload->>'id')::uuid;
      if v_id is null or length(coalesce(p_payload->>'name','')) not between 1 and 100
         or length(coalesce(p_payload->>'version','')) > 80 then return '{"error":"invalid_request","status":400}'::jsonb; end if;
      insert into beauty_game.events(id,session_hash,payload) values(v_id,p_session_hash,p_payload) on conflict do nothing;
      select * into v_existing from beauty_game.events where id = v_id;
      if v_existing.session_hash <> p_session_hash or v_existing.payload <> p_payload then
        return '{"error":"event_conflict","status":409}'::jsonb;
      end if;
    elsif p_action = 'answer' then
      if jsonb_typeof(p_payload->'reason') is distinct from 'string' then return '{"error":"invalid_request","status":400}'::jsonb; end if;
      v_reason := (p_payload->>'reason')::jsonb;
      if jsonb_typeof(v_reason) <> 'object' then return '{"error":"invalid_request","status":400}'::jsonb; end if;
      if (v_reason ? 'reasons') then
        if jsonb_typeof(v_reason->'reasons') <> 'array' then return '{"error":"invalid_request","status":400}'::jsonb; end if;
        if jsonb_array_length(v_reason->'reasons') > 40 or exists (select 1 from jsonb_array_elements(v_reason->'reasons') r(value) where jsonb_typeof(value) <> 'string') then
          return '{"error":"invalid_request","status":400}'::jsonb;
        end if;
      end if;
      if exists (select 1 from jsonb_each(v_reason) r(key,value) where key in ('shade','advice','note') and jsonb_typeof(value) not in ('string','null')) then
        return '{"error":"invalid_request","status":400}'::jsonb;
      end if;
      -- Experience belongs to the selected product, not just the play. The session
      -- lock serializes this cleanup with all answer/experience updates.
      delete from beauty_game.experiences e
      using beauty_game.answers a
      where a.session_hash = p_session_hash and a.play = v_play and a.character = v_character and a.test = v_test
        and a.product is distinct from p_payload->>'product'
        and e.session_hash = a.session_hash and e.play = a.play and e.character = a.character and e.test = a.test;
      insert into beauty_game.answers(session_hash,play,character,test,version,product,reason)
        values(p_session_hash,v_play,v_character,v_test,coalesce(p_payload->>'version',''),p_payload->>'product',v_reason)
        on conflict (session_hash,play,character,test) do update
        set version = excluded.version, product = excluded.product, reason = excluded.reason, updated_at = v_now;
    elsif p_action = 'experience' then
      if not exists (select 1 from beauty_game.answers where session_hash = p_session_hash and play = v_play and character = v_character and test = v_test) then
        return '{"error":"answer_required","status":409}'::jsonb;
      end if;
      insert into beauty_game.experiences(session_hash,play,character,test,experience)
        values(p_session_hash,v_play,v_character,v_test,p_payload->>'experience')
        on conflict (session_hash,play,character,test) do update set experience = excluded.experience, updated_at = v_now;
    elsif p_action = 'reflection' then
      insert into beauty_game.reflections(session_hash,play,character,test,mode,body,criteria,language)
        values(p_session_hash,v_play,v_character,v_test,p_payload->>'mode',p_payload->>'body',p_payload->'criteria',p_payload->>'language')
        on conflict (session_hash,play,character,test) do update
        set mode = excluded.mode, body = excluded.body, criteria = excluded.criteria, language = excluded.language, updated_at = v_now;
    elsif p_action = 'share' then
      if jsonb_typeof(p_payload->'snapshot') is distinct from 'object' then return '{"error":"invalid_request","status":400}'::jsonb; end if;
      select * into v_answer from beauty_game.answers where session_hash = p_session_hash and play = v_play and character = v_character and test = v_test;
      if not found then return '{"error":"answer_required","status":409}'::jsonb; end if;
      -- Allowlist public answer fields. Private note and unknown fields never leave this row.
      v_public_reason := jsonb_strip_nulls(jsonb_build_object('reasons',v_answer.reason->'reasons','shade',v_answer.reason->'shade','advice',v_answer.reason->'advice'));
      v_hash := encode(sha256(convert_to(jsonb_build_object('product',v_answer.product,'reason',v_public_reason,'snapshot',p_payload->'snapshot')::text,'UTF8')),'hex');
      insert into beauty_game.shares(session_hash,play,character,test,content_hash,product,reason,snapshot,channel)
        values(p_session_hash,v_play,v_character,v_test,v_hash,v_answer.product,v_public_reason,p_payload->'snapshot',coalesce(p_payload->>'channel','')) on conflict do nothing;
      select id into v_id from beauty_game.shares where session_hash = p_session_hash and play = v_play and character = v_character and test = v_test and content_hash = v_hash;
      return jsonb_build_object('ok',true,'id',v_id);
    end if;
    return '{"ok":true}'::jsonb;
  exception when invalid_text_representation or not_null_violation or foreign_key_violation or check_violation or string_data_right_truncation or numeric_value_out_of_range then
    return '{"error":"invalid_request","status":400}'::jsonb;
  end;
end;
$$;
revoke all on function public.beauty_game_command(text,text,jsonb) from public, anon, authenticated;
grant execute on function public.beauty_game_command(text,text,jsonb) to service_role;
comment on function public.beauty_game_command(text,text,jsonb) is 'Server-only replacement game API. Server supplies SHA256 of an opaque secure session cookie and validates account tokens before link. No unsigned legacy device ownership.';
commit;
